use vstd::prelude::*;

verus! {

fn solve(t: Vec<char>) -> (out: Vec<char>)
    ensures
        out@ == t@,
{
    // Input is assumed non-empty, but the logic works for empty as well.
    let n = t.len();
    let mut out: Vec<char> = Vec::with_capacity(n);

    // Measure for termination (conceptually): n - i, strictly decreases each iteration.
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            out.len() == i,
            out.len() <= n,
            // Prefix property: out matches t for the portion already copied
            forall|k: int| 0 <= k < i ==> out@[k] == t@[k],
        decreases
            n - i,
    {
        // Maintain prefix property: out[k] == t[k] for all k < out.len().
        out.push(t[i]);

        // After push, out.len() = old(out.len()) + 1 = old(i) + 1
        // so the invariant will re-establish with i incremented below.
        i += 1;
    }

    debug_assert_eq!(out.len(), n);

    // From the loop invariant at exit: i == n and forall k < n, out[k] == t[k]
    // hence out@ == t@.
    out
}

} // verus!

